WITH base AS (SELECT * FROM inventory WHERE store_id IN (3, 4, 5, 6) AND YEAR(last_restock) >= 2025), summary AS (SELECT DATE_FORMAT(last_restock, 'yyyy-MM') AS last_restock_month, COUNT(quantity) AS quantity_count, ROUND(STDDEV(quantity), 2) AS stddev_quantity FROM base GROUP BY DATE_FORMAT(last_restock, 'yyyy-MM')) SELECT last_restock_month, quantity_count, stddev_quantity FROM summary WHERE quantity_count > 8
